import math
from collections import defaultdict

WEIGHTS = {"outcome": .40, "complexity": .25, "leverage": .20, "ownership": .15}
DIMS = tuple(WEIGHTS)


def is_substantive_review(review: dict) -> bool:
    return review.get("state") == "CHANGES_REQUESTED" or len((review.get("body") or "").strip()) >= 80


def rank_engineers(prs: list[dict], classifications: dict) -> list[dict]:
    people: dict[str, dict] = defaultdict(lambda: {"raw":defaultdict(float),"prs":[],"reviews":[],"confidence":[]})
    for pr in prs:
        author = pr["author"]
        login = author["login"]
        classification = classifications[pr["number"]]
        record = classification.model_dump() if hasattr(classification, "model_dump") else classification
        impact = sum(record[d] * WEIGHTS[d] for d in DIMS) * 25 * record["confidence"]
        people[login].update({"login":login,"name":None,"avatar_url":author["avatarUrl"],"profile_url":author["url"]})
        people[login]["prs"].append({"title":pr["title"],"url":pr["url"],"kind":"pull_request","explanation":record["explanation"],"impact_score":round(impact,1)})
        people[login]["confidence"].append(record["confidence"])
        for dim in DIMS:
            people[login]["raw"][dim] += record[dim] * record["confidence"]
        for review in pr.get("reviews", {}).get("nodes", []):
            reviewer = review.get("author") or {}
            if reviewer.get("login") and reviewer["login"] != login and is_substantive_review(review):
                rlogin = reviewer["login"]
                people[rlogin].update({"login":rlogin,"name":None,"avatar_url":reviewer["avatarUrl"],"profile_url":reviewer["url"]})
                people[rlogin]["raw"]["leverage"] += .25 * record["confidence"]
                people[rlogin]["raw"]["ownership"] += .10 * record["confidence"]
                people[rlogin]["reviews"].append({"title":f"Review: {pr['title']}","url":review.get("url") or pr["url"],"kind":"review","explanation":"Substantive review that helped shape a shipped change.","impact_score":round(impact*.25,1)})
    for person in people.values():
        for dim in DIMS:
            person["raw"][dim] = math.log1p(person["raw"][dim])
    ranges = {dim:(min(p["raw"][dim] for p in people.values()),max(p["raw"][dim] for p in people.values())) for dim in DIMS}
    ranked = []
    for person in people.values():
        dimensions = {}
        for dim,(low,high) in ranges.items():
            dimensions[dim] = 50.0 if high == low else round((person["raw"][dim]-low)/(high-low)*100,1)
        score = round(sum(dimensions[d]*WEIGHTS[d] for d in DIMS),1)
        strongest = max(DIMS,key=lambda d: dimensions[d])
        evidence = sorted(person["prs"],key=lambda x:x["impact_score"],reverse=True)[:3]
        if len(evidence)<3:
            evidence += sorted(person["reviews"],key=lambda x:x["impact_score"],reverse=True)[:3-len(evidence)]
        if not evidence:
            continue
        ranked.append({**{k:person[k] for k in ("login","name","avatar_url","profile_url")},"score":score,"strongest_dimension":strongest,"dimensions":dimensions,"confidence":round(sum(person["confidence"])/len(person["confidence"]),2) if person["confidence"] else .4,"summary":f"Strongest visible impact is {strongest}, supported by {evidence[0]['title']}.","authored_prs":len(person["prs"]),"substantive_reviews":len(person["reviews"]),"evidence":evidence})
    ranked.sort(key=lambda p:(-p["score"],-p["dimensions"]["outcome"],p["login"]))
    for index,person in enumerate(ranked[:5],1): person["rank"] = index
    return ranked[:5]

