import json
import os
from typing import Any

from openai import OpenAI
from pydantic import BaseModel, Field


class Classification(BaseModel):
    number: int
    outcome: int = Field(ge=0, le=4)
    complexity: int = Field(ge=0, le=4)
    leverage: int = Field(ge=0, le=4)
    ownership: int = Field(ge=0, le=4)
    confidence: float = Field(ge=0, le=1)
    tags: list[str] = Field(max_length=3)
    explanation: str = Field(max_length=240)


class ClassificationBatch(BaseModel):
    items: list[Classification]


def fallback(pr: dict, reason: str) -> Classification:
    return Classification(number=pr["number"], outcome=1, complexity=1, leverage=1, ownership=1, confidence=.2, tags=["unclassified"], explanation=f"Classification unavailable: {reason[:180]}")


def classify_pull_requests(prs: list[dict[str, Any]]) -> dict[int, Classification]:
    if not os.getenv("OPENAI_API_KEY"):
        raise RuntimeError("OPENAI_API_KEY is required")
    client = OpenAI()
    model = os.getenv("OPENAI_MODEL", "gpt-5.5")
    output: dict[int, Classification] = {}
    for offset in range(0, len(prs), 20):
        batch = prs[offset:offset + 20]
        compact = [{"number":p["number"],"title":p["title"],"body":(p.get("body") or "")[:1600],"labels":[x["name"] for x in p.get("labels",{}).get("nodes",[])],"changed_files":p.get("changedFiles"),"issues":p.get("closingIssuesReferences",{}).get("nodes",[])} for p in batch]
        error = "unknown error"
        for _ in range(2):
            try:
                response = client.responses.parse(
                    model=model,
                    input=[
                        {"role":"system","content":"Assess demonstrated engineering impact, not activity volume. Rate outcome, complexity, leverage, and ownership 0-4. Diff size is context only. Be concise and evidence-bound."},
                        {"role":"user","content":json.dumps(compact)},
                    ],
                    text_format=ClassificationBatch,
                )
                parsed = response.output_parsed
                if not parsed:
                    raise ValueError("empty structured response")
                output.update({item.number:item for item in parsed.items})
                break
            except Exception as exc:
                error = str(exc)
        for pr in batch:
            output.setdefault(pr["number"], fallback(pr, error))
    return output

